func:
const ctrl = global.get('arrayPower');
if (!ctrl) return null;

if (!context.get('initialized')) {
    context.set('initialized', true);
    ctrl.init({
        isMock: false,
        portName: 'COM3',
        baudRate: 19200,
        address: 0x00,
        pollingIntervalMs: 0,
        limits: { maxVoltage_V: 30.0, maxCurrent_A: 3.0, maxPower_W: 90.0 }
    });
}

if (ctrl.sweepState && ctrl.sweepState.running) {
    return null;
}
await ctrl._pollTelemetry();
const t = ctrl.getTelemetry();
if (!t) return null;

const v = Number((t.voltage_V || 0).toFixed(2));
const i = Number((t.current_A || 0).toFixed(3));
const p = Number((t.power_W || 0).toFixed(2));
const setV = Number((ctrl.currentSetVoltage_V ?? t.setVoltage_V ?? 0).toFixed(2));
const maxI = Math.max(0.010, Number((ctrl.currentSetLimit_A ?? t.maxCurrent_A ?? 0.1).toFixed(3)));
const mode = (t.state && t.state.mode) ? t.state.mode : 'CV';
const outOn = !!(t.state && t.state.outputOn);
const sweeping = !!(ctrl.sweepState && ctrl.sweepState.running);
const connText = ctrl.isMock ? 'SIMULATOR (MOCK)' : ('HW 3645A: ' + ctrl.portName + ' @ ' + ctrl.baudRate);

const instPayload = {
    voltage_V: v,
    current_A: i,
    power_W: p,
    setVoltage_V: setV,
    maxCurrent_A: maxI,
    mode: mode,
    outputOn: outOn,
    sweeping: sweeping,
    connText: connText
};

// CSV Auto Logging
let logMsg = null;
const autoLog = flow.get('csvAutoLog') || false;
if (autoLog) {
    const fs = global.get('fs');
    const path = global.get('path');
    const logsDir = global.get('logsDir');
    if (fs && path && logsDir) {
        let logFile = flow.get('currentLogFile');
        if (!logFile) {
            const ts = new Date().toISOString().replace(/[:.]/g, '-');
            logFile = path.join(logsDir, 'array_telemetry_' + ts + '.csv');
            flow.set('currentLogFile', logFile);
            fs.writeFileSync(logFile, 'Timestamp,Voltage_V,Current_A,Power_W,Mode,OutputState\n', 'utf8');
        }
        const row = new Date().toISOString() + ',' + v.toFixed(2) + ',' + i.toFixed(3) + ',' + p.toFixed(2) + ',' + mode + ',' + (outOn ? 'ON' : 'OFF') + '\n';
        fs.appendFileSync(logFile, row, 'utf8');
        logMsg = { payload: 'Recording: ' + path.basename(logFile) };
    }
}

return [
    { payload: instPayload },
    { payload: instPayload },
    { payload: v },
    { payload: i },
    { payload: p },
    [
        { topic: 'Voltage (V)', payload: v },
        { topic: 'Current (A)', payload: i }
    ],
    logMsg
];

const ctrl = global.get('arrayPower');
if (!ctrl) return null;

const topic = msg.topic;
const val = msg.payload;
let logStatusMsg = null;

try {
    if (topic === 'output') {
        await ctrl.setOutput(Boolean(val));
    } else if (topic === 'estop') {
        ctrl.stopIVSweep();
        await ctrl.setOutput(false);
    } else if (topic === 'set_v') {
        const targetV = Math.round(Math.max(0, Math.min(ctrl.safetyLimits.maxVoltage_V, Number(val) || 0)) * 100) / 100;
        await ctrl.setVoltage(targetV);
    } else if (topic === 'set_i') {
        const targetI = Math.round(Math.max(0.010, Math.min(ctrl.safetyLimits.maxCurrent_A, Number(val) || 0.5)) * 1000) / 1000;
        await ctrl.setCurrentLimit(targetI);
    } else if (topic === 'step_v') {
        const delta = Number(val) || 0;
        const currentSetV = ctrl.currentSetVoltage_V || 0;
        const nextV = Math.round(Math.max(0, Math.min(ctrl.safetyLimits.maxVoltage_V, currentSetV + delta)) * 100) / 100;
        await ctrl.setVoltage(nextV);
    } else if (topic === 'csv_auto') {
        const enable = Boolean(val);
        flow.set('csvAutoLog', enable);
        if (!enable) {
            flow.set('currentLogFile', null);
            logStatusMsg = { payload: 'Auto CSV logging stopped.' };
        } else {
            logStatusMsg = { payload: 'Auto CSV logging started...' };
        }
    } else if (topic === 'csv_snapshot') {
        const fs = global.get('fs');
        const path = global.get('path');
        const logsDir = global.get('logsDir');
        const t = ctrl.getTelemetry();
        if (fs && path && logsDir && t) {
            const snapFile = path.join(logsDir, 'array_snapshots.csv');
            if (!fs.existsSync(snapFile)) {
                fs.writeFileSync(snapFile, 'Timestamp,Voltage_V,Current_A,Power_W,Mode,OutputState\n', 'utf8');
            }
            const row = new Date().toISOString() + ',' + Number(t.voltage_V).toFixed(2) + ',' + Number(t.current_A).toFixed(3) + ',' + Number(t.power_W).toFixed(2) + ',' + t.state.mode + ',' + (t.state.outputOn ? 'ON' : 'OFF') + '\n';
            fs.appendFileSync(snapFile, row, 'utf8');
            logStatusMsg = { payload: 'Snapshot saved: logs/array_snapshots.csv (' + new Date().toLocaleTimeString() + ')' };
        }
    }
} catch (err) {
    logStatusMsg = { payload: 'Error: ' + err.message };
}

const t = ctrl.getTelemetry();
const instPayload = {
    voltage_V: Number((t.voltage_V || 0).toFixed(2)),
    current_A: Number((t.current_A || 0).toFixed(3)),
    power_W: Number((t.power_W || 0).toFixed(2)),
    setVoltage_V: Number((ctrl.currentSetVoltage_V ?? 0).toFixed(2)),
    maxCurrent_A: Math.max(0.010, Number((ctrl.currentSetLimit_A ?? 0.5).toFixed(3))),
    mode: t.state?.mode || 'CV',
    outputOn: !!(t.state?.outputOn),
    connText: ctrl.isMock ? 'SIMULATOR (MOCK)' : ('HW 3645A: ' + ctrl.portName + ' @ ' + ctrl.baudRate)
};

return [{ payload: instPayload }, { payload: instPayload }, logStatusMsg];

const ctrl = global.get('arrayPower');
if (!ctrl) return null;

const topic = msg.topic;
const val = msg.payload;

if (topic === 'sweep_config' && val && typeof val === 'object') {
    flow.set('sweepStartV', Number(val.startV ?? 0.0));
    flow.set('sweepStopV',  Number(val.stopV  ?? 5.0));
    flow.set('sweepStepV',  Number(val.stepV  ?? 0.10));
    flow.set('sweepLimitI', Math.max(0.010, Number(val.limitI ?? 0.50)));
    return null;
}

if (topic === 'sweep_stop') {
    await ctrl.stopIVSweep();
    return [
        { payload: { status: 'Sweep stopped (Output OFF).', points: ctrl.sweepState.points || [] } },
        null,
        null,
        [
            { topic: 'Voltage (V)', payload: 0.0 },
            { topic: 'Current (A)', payload: 0.0 }
        ]
    ];
}

if (topic === 'sweep_run') {
    if (val && typeof val === 'object') {
        flow.set('sweepStartV', Number(val.startV ?? 0.0));
        flow.set('sweepStopV',  Number(val.stopV  ?? 5.0));
        flow.set('sweepStepV',  Number(val.stepV  ?? 0.10));
        flow.set('sweepLimitI', Math.max(0.010, Number(val.limitI ?? 0.50)));
    }
    const startV = Math.round((flow.get('sweepStartV') ?? 0.0) * 100) / 100;
    const stopV  = Math.round((flow.get('sweepStopV')  ?? 5.0) * 100) / 100;
    const stepV  = Math.max(0.01, Math.round((flow.get('sweepStepV') ?? 0.10) * 100) / 100);
    const limitI = Math.max(0.010, Math.round((flow.get('sweepLimitI') ?? 0.50) * 1000) / 1000);

    node.send([
        { payload: { status: 'Starting Sweep: ' + startV.toFixed(2) + 'V -> ' + stopV.toFixed(2) + 'V (ΔU=' + stepV.toFixed(2) + 'V, I_lim=' + limitI.toFixed(3) + 'A)...', points: [] } },
        null,
        null,
        null
    ]);

    try {
        const res = await ctrl.runIVSweep({
            startV,
            stopV,
            stepV,
            currentLimit_A: limitI,
            dwellMs: ctrl.isMock ? 200 : 450,
            onPoint: (pt) => {
                const liveMeter = {
                    voltage_V: pt.measuredVoltage_V,
                    current_A: pt.measuredCurrent_A,
                    power_W: pt.measuredPower_W,
                    setVoltage_V: pt.setVoltage_V,
                    maxCurrent_A: limitI,
                    mode: pt.mode,
                    outputOn: true,
                    sweeping: true,
                    connText: ctrl.isMock ? 'SIMULATOR (SWEEP)' : ('HW 3645A (SWEEP #' + pt.step + ')')
                };
                node.send([
                    {
                        payload: {
                            status: 'Step [#' + pt.step + ']: U_set=' + pt.setVoltage_V.toFixed(2) + 'V | U_meas=' + pt.measuredVoltage_V.toFixed(2) + 'V | I=' + pt.measuredCurrent_A.toFixed(3) + 'A (' + pt.mode + ')',
                            points: ctrl.sweepState.points.slice()
                        }
                    },
                    { payload: liveMeter },
                    { payload: pt.measuredVoltage_V },
                    [
                        { topic: 'Voltage (V)', payload: pt.measuredVoltage_V },
                        { topic: 'Current (A)', payload: pt.measuredCurrent_A }
                    ]
                ]);
            }
        });

        const fs = global.get('fs');
        const path = global.get('path');
        const logsDir = global.get('logsDir');
        let savedFileMsg = '';
        if (fs && path && logsDir && res.points.length > 0) {
            const ts = new Date().toISOString().replace(/[:.]/g, '-');
            const csvPath = path.join(logsDir, 'iv_sweep_' + ts + '.csv');
            const header = 'Step,Timestamp,SetVoltage_V,MeasuredVoltage_V,MeasuredCurrent_A,MeasuredPower_W,Mode\n';
            const body = res.points.map(p => p.step + ',' + p.timestamp + ',' + p.setVoltage_V.toFixed(2) + ',' + p.measuredVoltage_V.toFixed(2) + ',' + p.measuredCurrent_A.toFixed(3) + ',' + p.measuredPower_W.toFixed(2) + ',' + p.mode).join('\n') + '\n';
            fs.writeFileSync(csvPath, header + body, 'utf8');
            savedFileMsg = ' | Saved: logs/' + path.basename(csvPath);
        }

        return [
            {
                payload: {
                    status: 'Sweep completed (' + res.points.length + ' pts, status: ' + res.stopReason + ')' + savedFileMsg,
                    points: res.points
                }
            },
            null,
            null,
            [
                { topic: 'Voltage (V)', payload: 0.0 },
                { topic: 'Current (A)', payload: 0.0 }
            ]
        ];
    } catch (err) {
        return [
            {
                payload: {
                    status: 'Sweep error: ' + err.message,
                    points: ctrl.sweepState.points || []
                }
            },
            null,
            null,
            null
        ];
    }
}
return null;

const ctrl = global.get('arrayPower');
if (!ctrl) return null;

const topic = msg.topic;
const val = msg.payload;
let info = '';

try {
    if (topic === 'set_mock') {
        await ctrl.setMockMode(Boolean(val));
        info = 'Mode switched: ' + (ctrl.isMock ? 'Virtual Simulator (Mock)' : 'Physical Serial Port (' + ctrl.portName + ')');
    } else if (topic === 'set_com') {
        ctrl.portName = String(val);
        ctrl.serialTransport.portName = String(val);
        if (!ctrl.isMock) {
            await ctrl.setMockMode(false);
        }
        info = 'Serial COM port selected: ' + ctrl.portName;
    } else if (topic === 'set_baud') {
        ctrl.baudRate = Number(val) || 19200;
        ctrl.serialTransport.baudRate = ctrl.baudRate;
        info = 'Baud rate set to: ' + ctrl.baudRate;
    } else if (topic === 'set_address') {
        ctrl.address = Number(val) & 0xFF;
        if (ctrl.mockTransport && ctrl.mockTransport.mock) {
            ctrl.mockTransport.mock.address = ctrl.address;
        }
        info = 'Device address set to: ' + ctrl.address + ' (0x' + ctrl.address.toString(16).toUpperCase().padStart(2, '0') + ')';
    } else if (topic === 'set_poll') {
        ctrl.pollingIntervalMs = Math.max(100, Number(val) || 500);
        info = 'Polling interval set to: ' + ctrl.pollingIntervalMs + ' ms';
    } else if (topic === 'limit_v') {
        ctrl.setSafetyLimits({ maxVoltage_V: Number(val) || 30.0 });
        info = 'Software voltage limit: ' + ctrl.safetyLimits.maxVoltage_V + ' V';
    } else if (topic === 'limit_i') {
        ctrl.setSafetyLimits({ maxCurrent_A: Number(val) || 3.0 });
        info = 'Software current limit: ' + ctrl.safetyLimits.maxCurrent_A + ' A';
    } else if (topic === 'mock_load') {
        const ohms = Math.max(0.1, Number(val) || 10.0);
        ctrl.setVirtualLoad(ohms);
        info = 'Simulated load resistance: ' + ohms + ' Ω';
    }
} catch (err) {
    info = 'Configuration error: ' + err.message;
}

return { payload: info };
